/**
 * MAISON KHAN — Images de l'atelier : installation initiale (4 images).
 *
 * Ajoute les images du carrousel « Dans Notre Atelier » si la table est vide.
 * La section apparaît aussitôt sur l'accueil (chargement via /api/atelier-images,
 * aucun rebuild ni redémarrage nécessaire).
 *
 * Remplacez ces images à tout moment depuis l'admin :
 *   Produits → « Images de l'atelier » (ajout, légendes, ordre, suppression).
 *
 * Usage : bun scripts/seed-atelier.ts
 */
import { PrismaClient } from '@prisma/client'

const prisma = new PrismaClient()

const IMAGES = [
  {
    "image": "data:image/jpeg;base64,",
    "caption": "Sélection du cuir — nos peaux premium",
    "order": 1,
    "isActive": true
  },
  {
    "image": "data:image/jpeg;base64,",
    "caption": "Couture main — assemblage méticuleux",
    "order": 2,
    "isActive": true
  },
  {
    "image": "data:image/jpeg;base64,",
    "caption": "Nos créations prêtes à rejoindre la boutique",
    "order": 3,
    "isActive": true
  },
  {
    "image": "data:image/jpeg;base64,",
    "caption": "Contrôle qualité — la finition luxe",
    "order": 4,
    "isActive": true
  }
] as Array<{ image: string; caption: string | null; order: number; isActive: boolean }>

async function main() {
  const count = await prisma.atelierImage.count()
  if (count > 0) {
    console.log(`INFO : ${count} image(s) d'atelier déjà présentes — rien à faire.`)
    console.log("   (Pour les modifier : admin → Produits → Images de l'atelier)")
    return
  }
  for (const img of IMAGES) {
    await prisma.atelierImage.create({ data: img })
  }
  console.log(`OK : ${IMAGES.length} images d'atelier installées`)
  console.log("   La section « Dans Notre Atelier » apparaît maintenant sur la page d'accueil.")
  console.log("   Vérifiez : https://shop.maison-khan.com (Ctrl+F5) — après « Notre Savoir-Faire ».")
}

main()
  .catch((e) => { console.error('ERREUR :', e); process.exit(1) })
  .finally(() => prisma.$disconnect())
